// === Tab: mySketch ===
let gra;
let lapse = 0;    // mouse timer

function setup() {
	createCanvas(1112, 834,WEBGL);
	rectMode(CENTER);
	colorMode(HSB, 255);
	gra = createGraphics(width,height);
	gra.drawingContext.shadowOffsetX = 0;
  gra.drawingContext.shadowOffsetY = 0;
  gra.noStroke();
  gra.fill(0);

	//shader
	sh = createShader(vert,frag);
	this.shader(sh);
	sh.setUniform("u_resolution", [width,height]);
	pixelDensity(1);
}

function draw() {
	randomSeed(1);
	sh.setUniform("u_img", gra);

	gra.blendMode(BLEND);
	gra.background(0, 0, 0);
	gra.blendMode(SCREEN);

	const maxSize = max(width,height)*0.15;

	for(let i = 0; i < 50; i++){
		gra.drawingContext.shadowBlur = maxSize*0.4;
		gra.drawingContext.shadowColor = color(random(255),200,255);
		const x = (random(width) + frameCount*random(1,width*0.005))%(width+maxSize*3)-maxSize*1.5;
		const y = (random(height)+(sin(frameCount/random(20,50))+1)*random(height/4))%(height + maxSize*3)-maxSize*1.5;
		gra.ellipse(x, y, random(maxSize*0.2,maxSize));
	}
	rect(0,0,width,height);
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  }
} 

